#include <stdio.h>


int main(void)
{
    int a[3] = {2, 3, 5}, sum = 0;
    for (int i = 0; i < 3; i++) {
        if (5u & (1u << i)) {
            sum += a[i];
        }
    }
    printf("%d\n", sum);
    return 0;
}

#include <stdio.h>


int main(void)
{
    unsigned n = 0, count = 0;
    for (unsigned mask = 0; mask < (1u << n); mask++) {
        count++;
    }
    printf("%u\n", count);
    return 0;
}

